<?php use App\Models\Modules;use App\Core\DB; $type=$field['type'];$label=$field['label'];$inputId='field-'.$key;$required=!empty($field['required']);$value=$record[$key]??($field['default']??''); ?>
<div class="field <?=$type==='richtext'||$type==='textarea'?'wide':''?> <?=$errors[$key]??false?'invalid':''?>" data-field="<?=e($key)?>"><label for="<?=e($inputId)?>"><?=e($label)?> <?=$required?'<span class="required">*</span>':''?></label>
<?php if($type==='checkbox'):?><label class="switch"><input id="<?=e($inputId)?>" type="checkbox" name="<?=e($key)?>" value="1" <?=$value?'checked':''?>><span></span><em>Enabled</em></label>
<?php elseif($type==='richtext'):?><div class="rich-editor"><div class="rich-toolbar" role="toolbar" aria-label="Formatting"><button type="button" data-command="bold" aria-label="Bold"><b>B</b></button><button type="button" data-command="italic" aria-label="Italic"><i>I</i></button><button type="button" data-command="formatBlock" data-value="h2">Heading</button><button type="button" data-command="formatBlock" data-value="p">Paragraph</button><button type="button" data-command="insertUnorderedList">• List</button><button type="button" data-command="insertOrderedList">1. List</button><button type="button" data-command="createLink">Link</button><button type="button" data-command="removeFormat">Clear formatting</button></div><div class="rich-area" contenteditable="true" role="textbox" aria-multiline="true" aria-label="<?=e($label)?>"><?=rich($value)?></div><textarea id="<?=e($inputId)?>" class="rich-source" name="<?=e($key)?>" hidden><?=e($value)?></textarea></div>
<?php elseif($type==='textarea'):?><textarea id="<?=e($inputId)?>" name="<?=e($key)?>" rows="5" <?=$required?'required':''?>><?=e($value)?></textarea>
<?php elseif(in_array($type,['relation','select','multirelation','permissions'],true)):$multiple=in_array($type,['multirelation','permissions'],true);$options=$type==='select'?$field['options']:[];if($type==='permissions')$options=Modules::permissions();if(in_array($type,['relation','multirelation'],true)){foreach(App\Services\Options::search($field['table'],'',is_array($value)?$value:[$value]) as $option)$options[$option['id']]=$option['label'];}?>
<?php if(count($options)>12||in_array($type,['relation','multirelation'],true)):?><input class="select-search" type="search" placeholder="Type to narrow choices…" aria-label="Search <?=e($label)?>" data-select="<?=e($inputId)?>" <?php if(isset($field['table'])):?>data-table="<?=e($field['table'])?>"<?php endif?>><?php endif?><select id="<?=e($inputId)?>" name="<?=e($key)?><?=$multiple?'[]':''?>" <?=$required?'required':''?> <?=$multiple?'multiple size="5"':''?> <?=(($field['table']??'')==='media_files')?'data-media-select':''?>><?php if(!$multiple):?><option value="">Choose <?=e(strtolower($label))?></option><?php endif?><?php foreach($options as $optionValue=>$optionLabel):?><option value="<?=e($optionValue)?>" <?=($multiple?in_array($optionValue,is_array($value)?$value:[]):(string)$value===(string)$optionValue)?'selected':''?>><?=e($optionLabel)?></option><?php endforeach?></select>
<?php if(($field['table']??'')==='media_files'):?><div class="media-field-preview" data-for="<?=e($inputId)?>"><?=media_img(is_scalar($value)?$value:0,'Selected image')?></div><?php if(App\Services\Auth::can('media')):?><label class="upload-inline">↑ Upload file<input type="file" data-inline-upload="<?=e($inputId)?>" accept="image/jpeg,image/png,image/gif,image/webp,application/pdf,video/mp4,video/webm" hidden></label><?php endif?><?php endif?>
<?php else:$htmlType=match($type){'password'=>'password','email'=>'email','number'=>'number','datetime'=>'datetime-local',default=>'text'};if($type==='datetime'&&$value)$value=substr(str_replace(' ','T',$value),0,16);?><input id="<?=e($inputId)?>" type="<?=$htmlType?>" name="<?=e($key)?>" value="<?=e($type==='password'?'':$value)?>" <?=$required?'required':''?> <?=$type==='number'?'min="'.(int)($field['min']??0).'" max="'.(int)($field['max']??1000000).'"':''?> <?=$type==='password'?'autocomplete="new-password" minlength="12" maxlength="72"':''?> <?=$type==='slug'?'data-slug':''?> placeholder="<?=e($field['placeholder']??'')?>">
<?php endif?><?php if(!empty($field['help'])):?><small class="field-help"><?=e($field['help'])?></small><?php endif?><?php if(isset($errors[$key])):?><small class="field-error" role="alert"><?=e($errors[$key])?></small><?php endif?></div>
